#!/usr/bin/env python3
from pwn import *
import sys
import binascii
from itertools import combinations

def collect_data():
    r = remote('crypto.chal.csaw.io', 1337)
    r.recvuntil(b'Send me a random seed\n')
    r.sendline(b'1234567890123456')
    r.recvuntil(b'Encrypted flag:\n')

    encrypted_flags = []
    while True:
        try:
            enc = r.recvline().strip()
            if enc == b'Okay bye':
                break
            if enc and len(enc) >= 48:  # Filter for longest flags
                encrypted_flags.append(enc)
                if len(encrypted_flags) % 10 == 0:
                    print(f"[+] Got {len(encrypted_flags)} flags...")
        except:
            break

    r.close()
    return encrypted_flags

def xor_bytes(data1, data2):
    return bytes([a ^ b for a, b in zip(data1, data2)])

def try_decode(data):
    try:
        # Try to decode as ASCII, replacing non-printable chars
        text = ''.join(chr(b) if 32 <= b <= 126 else '.' for b in data)
        return text
    except:
        return None

def find_flag_format(text):
    if 'flag{' in text:
        start = text.index('flag{')
        end = text.find('}', start)
        if end != -1:
            return text[start:end+1]
    return None

def analyze_encryptions(encrypted_flags):
    if not encrypted_flags:
        print("[-] No encrypted flags to analyze")
        return

    print(f"[*] Got {len(encrypted_flags)} encrypted flags")
    print("[*] Starting analysis with all possible XOR combinations...")

    # Try XORing different combinations of blocks
    for i in range(2, 6):  # Try combining 2 to 5 blocks
        print(f"[*] Trying combinations of {i} blocks...")
        for blocks in combinations(encrypted_flags, i):
            # XOR all blocks together
            result = blocks[0]
            for block in blocks[1:]:
                result = xor_bytes(result, block)

            # Try to decode the result
            decoded = try_decode(result)
            if decoded:
                # Search for flag format
                flag = find_flag_format(decoded)
                if flag:
                    print(f"[+] Found flag candidate: {flag}")
                    print(f"[+] Full decoded text: {decoded}")
                    return flag
                # Look for interesting strings
                if any(x in decoded.lower() for x in ['flag', 'csaw', 'encrypt']):
                    print(f"[+] Interesting text found: {decoded}")

    print("[-] No flag found in XOR combinations")
    return None

def main():
    print("[*] Connecting to server...")
    encrypted_flags = collect_data()

    print("[*] Starting cryptanalysis...")
    flag = analyze_encryptions(encrypted_flags)

    if not flag:
        print("[-] Could not find flag")

if __name__ == '__main__':
    main()

