from pwn import *
import sys
import binascii
from itertools import combinations

def collect_data():
    r = remote('crypto.chal.csaw.io', 1337)
    r.recvuntil(b'Send me a random seed\n')
    r.sendline(b'1234567890123456')
    r.recvuntil(b'Encrypted flag:\n')

    encrypted_flags = []
    while True:
        try:
            enc = r.recvline().strip()
            if enc == b'Okay bye':
                break
            if enc and len(enc) >= 48:  # Filter for longest flags
                # Convert hex to bytes
                try:
                    enc_bytes = bytes.fromhex(enc.decode())
                    encrypted_flags.append(enc_bytes)
                    if len(encrypted_flags) % 10 == 0:
                        print(f"[+] Got {len(encrypted_flags)} flags...")
                except:
                    continue
        except:
            break

    r.close()
    return encrypted_flags

def xor_bytes(data1, data2):
    return bytes([a ^ b for a, b in zip(data1, data2)])

def try_decode(data):
    try:
        # Try to decode as ASCII, replacing non-printable chars
        text = ''.join(chr(b) if 32 <= b <= 126 else '.' for b in data)
        return text
    except:
        return None

def find_flag_format(text):
    if 'flag{' in text:
        start = text.index('flag{')
        end = text.find('}', start)
        if end != -1:
            return text[start:end+1]
    return None

def analyze_encryptions(encrypted_flags):
    if not encrypted_flags:
        print("[-] No encrypted flags to analyze")
        return

    print(f"[*] Got {len(encrypted_flags)} encrypted flags")
    print("[*] Starting analysis with pairs of blocks...")

    # First try pairs to find patterns
    seen_patterns = set()
    for block1, block2 in combinations(encrypted_flags, 2):
        result = xor_bytes(block1, block2)
        decoded = try_decode(result)
        pattern = decoded[:20] if decoded else None

        if pattern and pattern not in seen_patterns:
            seen_patterns.add(pattern)
            print(f"[+] Found pattern: {pattern}")

            # Look for flag format
            flag = find_flag_format(decoded)
            if flag:
                print(f"[+] Found potential flag: {flag}")
                print(f"[+] Full decoded text: {decoded}")
                return flag

    print("[*] Trying with groups of 3 blocks...")
    # Try combinations of 3 blocks with promising patterns
    for block1, block2, block3 in combinations(encrypted_flags[:20], 3):
        result = xor_bytes(xor_bytes(block1, block2), block3)
        decoded = try_decode(result)
        if decoded:
            flag = find_flag_format(decoded)
            if flag:
                print(f"[+] Found flag with 3 blocks: {flag}")
                print(f"[+] Full decoded text: {decoded}")
                return flag

    print("[-] No flag found in XOR combinations")
    return None

def main():
    print("[*] Connecting to server...")
    encrypted_flags = collect_data()

    print("[*] Starting cryptanalysis...")
    flag = analyze_encryptions(encrypted_flags)

    if not flag:
        print("[-] Could not find flag")

if __name__ == '__main__':
    main()

