def find_repeating_pattern(data, min_len=4):
    """Find repeating patterns in data"""
    n = len(data)
    for pattern_len in range(min_len, n//2):
        for i in range(n - pattern_len*2):
            pattern = data[i:i+pattern_len]
            if data.count(pattern) > 1:
                return pattern
    return None

def save_checkpoint(data, filename="checkpoint.json"):
    """Save data to checkpoint file"""
    with open(filename, 'w') as f:
        json.dump({
            'timestamp': datetime.now().isoformat(),
            'ciphertexts': [ct.hex() for ct in data]
        }, f)
    print(f"[+] Checkpoint saved to {filename}")

def load_checkpoint(filename="checkpoint.json"):
    """Load data from checkpoint file"""
    if not os.path.exists(filename):
        return None
    try:
        with open(filename, 'r') as f:
            data = json.load(f)
            return [bytes.fromhex(ct) for ct in data['ciphertexts']]
    except Exception as e:
        print(f"[-] Error loading checkpoint: {e}")
        return None

def connect_with_retry(host, port, max_retries=3, timeout=30):
    """Connect to server with retry mechanism"""
    for attempt in range(max_retries):
        try:
            print(f"[*] Connection attempt {attempt + 1}/{max_retries}")
            r = remote(host, port, timeout=timeout)
            print("[+] Connection successful!")
            return r
        except Exception as e:
            if attempt < max_retries - 1:
                print(f"[-] Connection failed: {e}")
                print(f"[*] Retrying in 5 seconds...")
                time.sleep(5)
            else:
                raise Exception(f"Failed to connect after {max_retries} attempts: {e}")

def collect_ciphertexts(r, target_count=100):
    """Collect ciphertexts with progress tracking"""
    ciphertexts = load_checkpoint()
    if ciphertexts:
        print(f"[+] Loaded {len(ciphertexts)} ciphertexts from checkpoint")
        return ciphertexts

    ciphertexts = []
    start_time = time.time()
    print(f"[*] Starting ciphertext collection. Target: {target_count}")

    try:
        while len(ciphertexts) < target_count:
            try:
                data = r.recvline(timeout=10).strip()
                if data:
                    ct = bytes.fromhex(data.decode())
                    if len(ct) > 0:
                        ciphertexts.append(ct)
                        if len(ciphertexts) % 10 == 0:
                            print(f"[+] Progress: {len(ciphertexts)}/{target_count} ciphertexts collected")
                            save_checkpoint(ciphertexts)

            except EOFError:
                print("[-] Connection closed unexpectedly")
                break
            except Exception as e:
                print(f"[-] Error collecting ciphertext: {e}")
                continue

    except KeyboardInterrupt:
        print("\n[-] Collection interrupted by user")
    finally:
        elapsed = time.time() - start_time
        print(f"[*] Collection finished. Time elapsed: {elapsed:.2f}s")
        save_checkpoint(ciphertexts)

    return ciphertexts

def analyze_ciphertexts(ciphertexts):
    """Analyze collected ciphertexts"""
    print(f"\n[*] Analyzing {len(ciphertexts)} ciphertexts")
    potential_flags = []

    total_pairs = (len(ciphertexts) * (len(ciphertexts) - 1)) // 2
    pair_count = 0

    for i in range(len(ciphertexts)):
        for j in range(i+1, len(ciphertexts)):
            pair_count += 1
            if pair_count % 100 == 0:
                print(f"[*] Analysis progress: {pair_count}/{total_pairs} pairs")

            xored = xor_bytes(ciphertexts[i], ciphertexts[j])

            # Look for ASCII text
            printable = ''
            for b in xored:
                if 32 <= b <= 126:
                    printable += chr(b)
                else:
                    printable += '.'

            # Check for interesting patterns
            if 'flag{' in printable.lower() or 'FLAG{' in printable:
                print(f"\n[!] Found potential flag pattern!")
                print(f"[+] ASCII: {printable}")
                print(f"[+] Hex: {xored.hex()}")
                potential_flags.append(printable)

            # Look for repeating patterns
            pattern = find_repeating_pattern(xored)
            if pattern:
                print(f"\n[!] Found repeating pattern:")
                print(f"[+] Pattern (hex): {pattern.hex()}")

    return potential_flags

def main():
    # Configure connection
    context.log_level = 'info'
    host = 'crypto.chal.csaw.io'
    port = 1337

    try:
        # Connect to server with retry mechanism
        r = connect_with_retry(host, port)

        # Receive initial prompt
        r.recvuntil(b'Send me a random seed\n')

        # Send seed
        print("[*] Sending seed...")
        r.sendline(b'1337')

        # Receive encrypted flag header
        print("[*] Waiting for encrypted flag...")
        r.recvuntil(b'Encrypted flag:\n')

        # Collect ciphertexts
        ciphertexts = collect_ciphertexts(r)

        if len(ciphertexts) < 2:
            print("[-] Not enough ciphertexts collected")
            return

        # Analyze ciphertexts
        potential_flags = analyze_ciphertexts(ciphertexts)

        if potential_flags:
            print("\n[+] Analysis complete! Found potential flags:")
            for flag in potential_flags:
                print(f"[+] {flag}")
        else:
            print("\n[-] No potential flags found")

    except Exception as e:
        print(f"[-] Fatal error: {str(e)}")
        print("[*] Stack trace:")
        import traceback
        traceback.print_exc()
    finally:
        try:
            r.close()
        except:
            pass

if __name__ == '__main__':
    main()

